def f(I):
    H=len(I);W=len(I[0])
    cnt=Counter(x for row in I for x in row)
    bg=cnt.most_common(1)[0][0]
    rare=min((c for c in cnt if c!=bg), key=lambda c:cnt[c])
    se=sorted((r,c) for r in range(H) for c in range(W) if I[r][c]==rare)
    oc=[c for c in cnt if c not in (bg,rare)]
    obs={(r,c) for r in range(H) for c in range(W) if I[r][c] in oc}
    def sgn(a): return (a>0)-(a<0)
    dr0,dc0=sgn(se[-1][0]-se[0][0]),sgn(se[-1][1]-se[0][1])
    # choose direction along seed line that reaches an obstacle before exiting
    def reach(d,start):
        rr,cc=start; k=1; hit=None
        while True:
            nr,nc=rr+d[0]*k,cc+d[1]*k
            if not(0<=nr<H and 0<=nc<W): return False
            if (nr,nc) in obs: hit=True; break
            k+=1
        return hit
    cands=[]
    for d in [(dr0,dc0),(-dr0,-dc0)]:
        start = se[-1] if d==(dr0,dc0) else se[0]
        if reach(d,start): cands.append((d,start))
    d,start=cands[0]
    O=[row[:] for row in I]
    def paint(r,c,d):
        for k in range(1,400):
            nr,nc=r+d[0]*k,c+d[1]*k
            if not(0<=nr<H and 0<=nc<W) or (nr,nc) in obs or I[nr][nc]==rare: return
            O[nr][nc]=3
    # walk ray; at obstacle, reflect
    r,c=start
    while True:
        nr,nc=r+d[0],c+d[1]
        if not(0<=nr<H and 0<=nc<W) or (nr,nc) in obs:
            # flip component whose move is blocked; prefer blocked-comp, validate
            if (nr,c) in obs:
                cand_d=(d[0],-d[1])
            elif (r,nc) in obs:
                cand_d=(-d[0],d[1])
            else:
                cand_d=(d[0],-d[1])
            if 0<=r+cand_d[0]<H and 0<=c+cand_d[1]<W and I[r+cand_d[0]][c+cand_d[1]] not in obs and I[r+cand_d[0]][c+cand_d[1]]!=rare:
                d=cand_d
            else:
                d=(-d[0],d[1])
            continue
        r,c=nr,nc
        paint(r,c,d)
        break  # one bounce only (matches all demos)
    return O
